345	     *  the figure for every full 30 days past the day it is due by, rounded as the claim rounds; 0.00 when not overdue,
346	     *  it has no figure, or it is a correction. */
347	    public static BigDecimal lateCharge(Claim claim, BigDecimal figure, Sheet sheet) {
348	        BigDecimal none = BigDecimal.ZERO.setScale(2);
349	        if (figure == null || claim.getStatus() != ClaimStatus.OPEN || claim.isCorrection()) {
350	            return none;
351	        }
352	        long periods = ChronoUnit.DAYS.between(claim.getDate().plusDays(sheet.getTerms()), sheet.getToday()) / 30;
353	        return periods <= 0 ? none : dueOn(figure, sheet.getLatePct().multiply(BigDecimal.valueOf(periods)),
354	                sheet.roundingFor(claim.getDate()));
355	    }
356	
357	    /** A claim's live figure at a rate: its due on its amount, rounded as the claim rounds, raised to the sheet's
358	     *  floor unless it is a correction. */
359	    public static BigDecimal liveFigure(Claim claim, BigDecimal rate, BigDecimal floor, RoundingMode rounding) {
360	        BigDecimal due = dueOn(claim.getAmount(), rate, rounding);
361	        return claim.isCorrection() ? due : floored(due, floor);
362	    }
363	
364	    /** A live due raised to the sheet's floor when it is below it. */
365	    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
366	        return floor != null && due.compareTo(floor) < 0 ? floor : due;
367	    }
368	
369	    private static BigDecimal scaled(BigDecimal amount) {
370	        return amount.setScale(2, RoundingMode.UNNECESSARY);
371	    }
372	
373	    private static String noteOf(String note) {
374	        return note == null ? "" : note.trim();
375	    }
376	}
