378	import { Component, computed, inject, input, output, signal } from '@angular/core';
379	import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
380	import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
381	import { CLAIM_AMOUNT_PATTERN, ClaimStatus, ClaimView, Claims, cents, countsWhile, dueBy, isOverdue, money, roundingDate } from '../../core/claims';
382	import { Grade, PersonView, gradeOn } from '../../core/people';
383	import { PeriodView, periodOn } from '../../core/periods';
384	import { DEFAULT_DUE_TERMS, NOT_AVAILABLE, RateView, claimDueCents } from '../../core/rates';
385	import { Session } from '../../core/session';
386	import { DEFAULT_TERMS, Sheets } from '../../core/sheet';
387	
388	const NO_RATES: readonly RateView[] = [];
389	
390	// One person's claims: their claimed total, one form to add a claim or edit an existing one, and
391	// the claims listed newest first.
392	@Component({
393	  selector: 'app-person-claims',
394	  imports: [ReactiveFormsModule],
395	  template: `
396	    <p>Claimed: <span data-testid="person-claimed">{{ claimed() }}</span></p>
397	
398	    <form [formGroup]="form" (ngSubmit)="submit()"
399	          [attr.aria-label]="(editingId() === null ? 'Add a claim for ' : 'Edit a claim of ') + personName()">
400	      <label [for]="fieldId('amount')">Amount</label>
401	      <input [id]="fieldId('amount')" data-testid="claim-form-amount" formControlName="amount"
402	             inputmode="decimal" autocomplete="off" />
403	      <label [for]="fieldId('date')">Date</label>
404	      <input [id]="fieldId('date')" type="date" data-testid="claim-form-date" formControlName="date" />
405	      <label [for]="fieldId('note')">Note</label>
406	      <input [id]="fieldId('note')" data-testid="claim-form-note" formControlName="note" autocomplete="off" />
407	      <label [for]="fieldId('corrects')">Corrects claim No.</label>
408	      <input [id]="fieldId('corrects')" data-testid="claim-form-corrects" formControlName="corrects"
409	             inputmode="numeric" autocomplete="off" />
410	      <button type="submit" data-testid="claim-form-submit" [disabled]="saving()">
411	        {{ editingId() === null ? 'Add claim' : 'Save claim' }}
412	      </button>
413	      @if (error(); as err) {
414	        <p role="alert" data-testid="claim-form-error">{{ err }}</p>
415	      }
416	    </form>
417	
418	    <ul [attr.aria-label]="'Claims of ' + personName()">
419	      @for (c of claims(); track c.id) {
420	        <li [attr.data-testid]="'claim-row-' + c.id">
421	          No. <span data-testid="claim-number">{{ c.number ?? '' }}</span>
422	          <span data-testid="claim-amount">{{ c.amount }}</span>
423	          on <span data-testid="claim-date">{{ c.date }}</span>
424	          — due <span data-testid="claim-due">{{ dueOf(c) }}</span>
425	          by <span data-testid="claim-due-by">{{ dueByOf(c) }}</span>
426	          — overdue <span data-testid="claim-overdue">{{ overdueOf(c) ? 'yes' : 'no' }}</span>
427	          in period <span data-testid="claim-period">{{ periodOf(c) }}</span>
428	          <span data-testid="claim-note">{{ c.note }}</span>
429	          corrects No. <span data-testid="claim-corrects">{{ c.corrects ?? '' }}</span>
430	          <span data-testid="claim-status">{{ c.status }}</span>
431	          opened by <span data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</span>
432	          — stated <span data-testid="claim-stated">{{ c.stated ? 'yes' : 'no' }}</span>
433	          <button type="button" data-testid="claim-open" (click)="changeStatus(c, 'OPEN')"
434	                  [attr.aria-label]="'Open claim of ' + c.amount + ' on ' + c.date">Open</button>
435	          <button type="button" data-testid="claim-settle" (click)="changeStatus(c, 'SETTLED')"
436	                  [attr.aria-label]="'Settle claim of ' + c.amount + ' on ' + c.date">Settle</button>
437	          <button type="button" data-testid="claim-void" (click)="changeStatus(c, 'VOID')"
438	                  [attr.aria-label]="'Void claim of ' + c.amount + ' on ' + c.date">Void</button>
439	          @if (editingId() === c.id) {
440	            <button type="button" data-testid="claim-cancel" (click)="reset()">Cancel</button>
441	          } @else {
442	            <button type="button" data-testid="claim-edit" (click)="edit(c)"
443	                    [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date">Edit</button>
444	          }
445	          @if (claimError()?.id === c.id) {
446	            <p role="alert" data-testid="claim-error">{{ claimError()?.message }}</p>
447	          }
448	        </li>
449	      }
450	    </ul>
451	  `,
452	})
453	export class PersonClaims {
454	  private readonly sheets = inject(Sheets);
455	  private readonly session = inject(Session);
456	  private readonly api = inject(Claims);
457	
458	  readonly personId = input.required<number>();
459	  readonly personName = input.required<string>();
460	  /** This person's claims, newest first. */
461	  readonly claims = input.required<ClaimView[]>();
462	  /** The rates of each grade, in the order they take effect. */
463	  readonly ratesByGrade = input.required<ReadonlyMap<Grade, readonly RateView[]>>();
464	  /** This person's grades: a claim is at the one in force on its date. */
465	  readonly grades = input.required<Pick<PersonView, 'grade' | 'grades'>>();
466	  /** The sheet's periods, by from-date. */
467	  readonly periods = input.required<readonly PeriodView[]>();
468	  /** Whether the person is on hold: their OPEN claims then count in no total. */
469	  readonly held = input(false);
470	  readonly saved = output<ClaimView>();
471	
472	  protected readonly claimed = computed(() => money(this.claims().filter(countsWhile(this.held())).reduce((sum, c) => sum + cents(c.amount), 0)));
473	  protected readonly editingId = signal<number | null>(null);
474	  protected readonly error = signal<string | null>(null);
475	  protected readonly saving = signal(false);
476	  /** The error of the last action taken on a claim's row, until the next action on that row. */
477	  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
478	
479	  protected readonly form = new FormGroup({
480	    amount: new FormControl('', { nonNullable: true }),
481	    date: new FormControl('', { nonNullable: true }),
482	    note: new FormControl('', { nonNullable: true }),
483	    corrects: new FormControl('', { nonNullable: true }),
484	  });
485	
486	  constructor() {
487	    // An error is removed as soon as its form is changed.
488	    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
489	  }
490	
491	  protected dueOf(c: ClaimView): string {
492	    const rates = this.ratesByGrade().get(gradeOn(this.grades(), c.date)) ?? NO_RATES;
493	    const due = claimDueCents(c, rates, this.sheets.current() ?? DEFAULT_DUE_TERMS, roundingDate(c, this.claims()));
494	    return due === null ? NOT_AVAILABLE : money(due);
495	  }
496	
497	  protected dueByOf(c: ClaimView): string {
498	    return dueBy(c, this.sheets.current()?.terms ?? DEFAULT_TERMS);
499	  }
500	
501	  protected overdueOf(c: ClaimView): boolean {
502	    const sheet = this.sheets.current();
503	    return sheet !== null && isOverdue(c, sheet.terms, sheet.today);
504	  }
505	
506	  protected periodOf(c: ClaimView): string {
507	    return periodOn(this.periods(), c.date)?.name ?? '';
508	  }
509	
510	  protected changeStatus(c: ClaimView, status: ClaimStatus): void {
511	    this.claimError.set(null);
512	    const sheet = this.sheets.current();
513	    if (!sheet) return;
514	    this.api.changeStatus(sheet.id, c.id, status).subscribe({
515	      next: (saved) => this.saved.emit(saved),
516	      error: (err: unknown) => this.claimError.set({
517	        id: c.id,
518	        message: err instanceof HttpErrorResponse && err.status === 403
519	          ? c.openedBy === this.session.user()
520	            ? 'You opened this claim, so someone else must settle it.'
521	            : 'Its due is above the clerk limit, so a steward must settle it.'
522	          : err instanceof HttpErrorResponse && err.status === 423
523	            ? 'This claim is dated inside a closed period.'
524	            : `A ${c.status} claim cannot become ${status}.`,
525	      }),
526	    });
527	  }
528	
529	  protected fieldId(field: string): string {
530	    return `claim-form-${field}-${this.personId()}`;
531	  }
532	
533	  protected edit(c: ClaimView): void {
534	    this.claimError.set(null);
535	    // Only a draft can be edited; an open claim is changed by voiding it and adding a new one.
536	    if (c.status !== 'DRAFT') {
537	      this.claimError.set({ id: c.id, message: `A ${c.status} claim cannot be edited. Void it and add a new one.` });
538	      return;
539	    }
540	    this.editingId.set(c.id);
541	    this.form.setValue({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects === null ? '' : String(c.corrects) },
542	      { emitEvent: false });
543	    this.error.set(null);
544	  }
545	
546	  protected reset(): void {
547	    this.editingId.set(null);
548	    this.form.reset({ amount: '', date: '', note: '', corrects: '' }, { emitEvent: false });
549	    this.error.set(null);
550	  }
551	
552	  protected submit(): void {
553	    // A second submit before the first has answered is ignored, so it stores one record.
554	    if (this.saving()) return;
555	    this.error.set(null);
556	    const sheet = this.sheets.current();
557	    if (!sheet) return;
558	    const value = this.form.getRawValue();
559	    const amount = value.amount.trim();
560	    if (!CLAIM_AMOUNT_PATTERN.test(amount)) {
561	      this.error.set('Type an amount with up to two decimals; a negative one is a correction.');
562	      return;
563	    }
564	    // A negative amount is a correction: it must name the number of a settled claim of this person.
565	    const correction = amount.startsWith('-');
566	    const corrects = value.corrects.trim();
567	    if (correction && !/^\d+$/.test(corrects)) {
568	      this.error.set('A negative amount is a correction: type the number of the settled claim it corrects.');
569	      return;
570	    }
571	    if (!correction && corrects !== '') {
572	      this.error.set('Only a negative amount (a correction) names a claim it corrects.');
573	      return;
574	    }
575	    const date = value.date.trim();
576	    if (date !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
577	      this.error.set('Choose a date for the claim, or leave it blank for today.');
578	      return;
579	    }
580	    const claim = { amount, date: date === '' ? null : date, note: value.note, corrects: correction ? Number(corrects) : null };
581	    const id = this.editingId();
582	    this.saving.set(true);
583	    const request = id === null ? this.api.add(sheet.id, this.personId(), claim) : this.api.update(sheet.id, id, claim);
584	    request.subscribe({
585	      next: (saved) => {
586	        this.saving.set(false);
587	        this.saved.emit(saved);
588	        this.reset();
589	      },
590	      error: (err: unknown) => {
591	        this.saving.set(false);
592	        this.error.set(
593	          err instanceof HttpErrorResponse && err.status === 423
594	            ? 'That claim is dated inside a closed period.'
595	            : err instanceof HttpErrorResponse && err.status === 422
596	              ? 'That claim is dated after the person retired.'
597	            : correction && err instanceof HttpErrorResponse && err.status === 400
598	              ? `Claim No. ${corrects} is not a settled claim of ${this.personName()}, so this cannot correct it.`
599	            : id !== null && err instanceof HttpErrorResponse && err.status === 409
600	              ? 'Only a draft claim can be edited. Void it and add a new one.'
601	              : id === null ? 'Could not add that claim.' : 'Could not save that claim.',
602	        );
603	      },
604	    });
605	  }
606	}
607	import { HttpClient } from '@angular/common/http';
608	import { Injectable, inject } from '@angular/core';
609	import { Observable } from 'rxjs';
610	import { PersonView } from './people';
611	
612	/** DRAFT when added, then OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID. */
613	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
614	
615	export interface ClaimView {
616	  id: number;
617	  personId: number;
618	  /** The amount with exactly two decimals, e.g. "10.50". */
619	  amount: string;
620	  /** yyyy-mm-dd */
621	  date: string;
622	  note: string;
623	  status: ClaimStatus;
624	  /** The claim's number on its sheet, given when opened; null while a draft or once void. */
625	  number: number | null;
626	  /** The due fixed when the claim was settled, with exactly two decimals; null while it is not
627	   *  settled, or if its grade had no rate then (its due then follows the rate as an open one does). */
628	  settledDue: string | null;
629	  /** The signed-in name of the user who opened the claim; null while a draft. */
630	  openedBy: string | null;
631	  /** Whether its person's last statement binds the claim, to `statedDue`. */
632	  stated: boolean;
633	  /** The figure the claim had at its person's last statement, while bound by it, with exactly two
634	   *  decimals; null when not bound, or if it had no figure then (it then follows the rate). */
635	  statedDue: string | null;
636	  /** The number of the SETTLED claim of the same person a correction (a negative amount) corrects; null on
637	   *  any other claim. */
638	  corrects: number | null;
639	}
640	
641	/** Only OPEN and SETTLED claims count toward what is claimed and due. */
642	export function counts(c: ClaimView): boolean {
643	  return c.status === 'OPEN' || c.status === 'SETTLED';
644	}
645	
646	/** Whether the claim counts in the live totals for a person held or not: while held, only SETTLED ones do. */
647	export function countsWhile(held: boolean): (c: ClaimView) => boolean {
648	  return held ? (c) => c.status === 'SETTLED' : counts;
649	}
650	
651	/** The date (yyyy-mm-dd) that decides how a claim's live figures round: its own, or for a correction the date
652	 *  of the claim of the same person it corrects, found among that person's claims. */
653	export function roundingDate(
654	  c: Pick<ClaimView, 'date' | 'corrects'>,
655	  theirs: readonly Pick<ClaimView, 'date' | 'number'>[],
656	): string {
657	  if (c.corrects === null) return c.date;
658	  return theirs.find((o) => o.number === c.corrects)?.date ?? c.date;
659	}
660	
661	/** The day a claim is due by (yyyy-mm-dd): its date plus the sheet's terms in days. */
662	export function dueBy(c: Pick<ClaimView, 'date'>, terms: number): string {
663	  const [y, m, d] = c.date.split('-').map(Number);
664	  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
665	}
666	
667	/** Whether a claim is overdue on the sheet's today: OPEN and due by a day before it. */
668	export function isOverdue(c: Pick<ClaimView, 'date' | 'status'>, terms: number, today: string): boolean {
669	  return c.status === 'OPEN' && dueBy(c, terms) < today;
670	}
671	
672	/** A claim as the form submits it: a blank date takes the sheet's today. A negative amount is a correction,
673	 *  which names in `corrects` the number of the claim it corrects. */
674	export interface ClaimForm {
675	  amount: string;
676	  date: string | null;
677	  note: string;
678	  corrects: number | null;
679	}
680	
681	/** What a quick-add made: the person the claim is for, whether they were added by it, and the claim. */
682	export interface QuickAddView {
683	  person: PersonView;
684	  personAdded: boolean;
685	  claim: ClaimView;
686	}
687	
688	/** An amount the form accepts: 0.00 or more, with up to two decimals. */
689	export const AMOUNT_PATTERN = /^\d+(\.\d{1,2})?$/;
690	
691	/** An amount the claim form accepts: AMOUNT_PATTERN, or a negative one (a correction). */
692	export const CLAIM_AMOUNT_PATTERN = /^-?\d+(\.\d{1,2})?$/;
693	
694	/** An amount ("12.3", "4", "-0.5") in whole cents, so sums are exact. */
695	export function cents(amount: string): number {
696	  const negative = amount.startsWith('-');
697	  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
698	  const total = Number(whole) * 100 + Number(frac.padEnd(2, '0').slice(0, 2));
699	  return negative ? -total : total;
700	}
701	
702	/** Whole cents as an amount with two decimals, e.g. "-0.30". */
703	export function money(total: number): string {
704	  const abs = Math.abs(total);
705	  return `${total < 0 ? '-' : ''}${Math.trunc(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
706	}
707	
708	// The claims people on a sheet have made, listed newest first.
709	@Injectable({ providedIn: 'root' })
710	export class Claims {
711	  private readonly http = inject(HttpClient);
712	
713	  list(sheetId: string): Observable<ClaimView[]> {
714	    return this.http.get<ClaimView[]>(`${this.base(sheetId)}/claims`);
715	  }
716	
717	  add(sheetId: string, personId: number, claim: ClaimForm): Observable<ClaimView> {
718	    return this.http.post<ClaimView>(`${this.base(sheetId)}/people/${personId}/claims`, claim);
719	  }
720	
721	  /** Add a DRAFT claim for the person named `name`, dated the sheet's today; one not on the sheet is
722	   *  added first with grade A. Refused as a whole when the person or the claim is. */
723	  quickAdd(sheetId: string, name: string, amount: string): Observable<QuickAddView> {
724	    return this.http.post<QuickAddView>(`${this.base(sheetId)}/quick-add`, { name, amount });
725	  }
726	
727	  update(sheetId: string, id: number, claim: ClaimForm): Observable<ClaimView> {
728	    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}`, claim);
729	  }
730	
731	  changeStatus(sheetId: string, id: number, status: ClaimStatus): Observable<ClaimView> {
732	    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/status`, { status });
733	  }
734	
735	  private base(sheetId: string): string {
736	    return `/api/sheets/${encodeURIComponent(sheetId)}`;
737	  }
738	}
